import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { createPoll } from "../api/polls";

export default function CreatePollPage() {
  const [question, setQuestion] = useState("");
  const [channelId, setChannelId] = useState("");
  const [choices, setChoices] = useState(["", ""]);
  const [message, setMessage] = useState("");
  const token = localStorage.getItem("token");
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await createPoll({ question, channelId, choices }, token);
      setMessage("✅ Опитування створено!");
      navigate("/"); // або інша сторінка після успіху
    } catch (err) {
      console.error(err);
      setMessage("❌ Помилка створення опитування");
    }
  };

  const handleChoiceChange = (index, value) => {
    const newChoices = [...choices];
    newChoices[index] = value;
    setChoices(newChoices);
  };

  const addChoice = () => setChoices([...choices, ""]);

  return (
    <div>
      <h2>Створити опитування</h2>
      {message && <p>{message}</p>}
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          placeholder="Питання"
          value={question}
          onChange={(e) => setQuestion(e.target.value)}
          required
        />
        {choices.map((c, i) => (
          <input
            key={i}
            type="text"
            placeholder={`Варіант ${i + 1}`}
            value={c}
            onChange={(e) => handleChoiceChange(i, e.target.value)}
            required
          />
        ))}
        <button type="button" onClick={addChoice}>Додати варіант</button>
        <input
          type="text"
          placeholder="ID каналу"
          value={channelId}
          onChange={(e) => setChannelId(e.target.value)}
          required
        />
        <button type="submit">Створити</button>
      </form>
    </div>
  );
}
